package bookstore

// Cost returns the total cost, in cents, of buying the given basket of
// books from the series, applying the largest possible discount.
//
// Books are identified by the integers 1-5. One copy of any book costs
// 800 cents. A group of k distinct titles is priced at 800 cents per
// book, minus a discount of 5% (k=2), 10% (k=3), 20% (k=4) or 25% (k=5).
func Cost(books []int) int {
	var counts [5]int
	for _, b := range books {
		if b >= 1 && b <= 5 {
			counts[b-1]++
		}
	}
	sortDesc(&counts)
	return minCost(counts, make(map[[5]int]int))
}

// groupCost[k] is the total cost, in cents, of a group of k distinct
// titles, i.e. 800 cents per book after the discount for that group size.
var groupCost = [6]int{0, 800, 1520, 2160, 2560, 3000}

// minCost returns the minimum cost of the books described by counts,
// which must be sorted in non-increasing order. It considers every
// possible first group — any subset of the titles that still have
// copies left — and memoizes subproblems.
func minCost(counts [5]int, memo map[[5]int]int) int {
	if counts[0] == 0 {
		return 0
	}
	if cost, ok := memo[counts]; ok {
		return cost
	}

	k := 0
	for k < 5 && counts[k] > 0 {
		k++
	}

	// Buying every book without any discount bounds the optimum from above.
	best := 800 * (counts[0] + counts[1] + counts[2] + counts[3] + counts[4])

	for mask := 1; mask < 1<<k; mask++ {
		next := counts
		size := 0
		for i := 0; i < k; i++ {
			if mask&(1<<i) != 0 {
				next[i]--
				size++
			}
		}
		sortDesc(&next)
		if cost := groupCost[size] + minCost(next, memo); cost < best {
			best = cost
		}
	}

	memo[counts] = best
	return best
}

// sortDesc sorts the five counts in non-increasing order.
func sortDesc(c *[5]int) {
	for i := 0; i < 4; i++ {
		for j := i + 1; j < 5; j++ {
			if c[j] > c[i] {
				c[i], c[j] = c[j], c[i]
			}
		}
	}
}

